/*
 * prog53_dfs_cycle
 *
 * The original binary implements a tiny directed‑graph cycle detector.
 * It expects the command line arguments to be a list of vertex pairs
 * (u v) describing edges u → v.  Vertices are numbered 0 … 7.
 *
 *   ./prog53_dfs_cycle u1 v1 u2 v2 … uk vk
 *
 * If the input is malformed (odd number of arguments, a vertex outside
 * the range 0‑7, or a non‑numeric argument) the program prints
 *   INVALID_INPUT
 * and exits with status 1.
 *
 * Otherwise it builds an 8×8 adjacency matrix, runs a depth‑first search
 * on the graph and prints either
 *   CYCLE    – if a directed cycle exists, or
 *   ACYCLIC  – if the graph is acyclic.
 *
 * The implementation below follows the logic of the de‑compiled
 * state‑machine while using clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXV 8                     /* maximum number of vertices */

static int  adj[MAXV][MAXV];        /* adjacency matrix: adj[dest][src] = 1 */
static int  color[MAXV];           /* 0 = white, 1 = gray, 2 = black */
static bool found_cycle = false;   /* set to true when a back‑edge is seen */

/* ------------------------------------------------------------------ */
/* Depth‑first search that follows the adjacency matrix layout used
   by the original binary (adj[dest][src] == 1 means an edge src → dest). */
static void dfs(int src)
{
    if (found_cycle)               /* early exit if a cycle is already known */
        return;

    color[src] = 1;                /* gray – vertex is being explored */

    for (int dest = 0; dest < MAXV; ++dest) {
        if (adj[dest][src] == 0)   /* no edge src → dest */
            continue;

        if (color[dest] == 0) {    /* white – not visited yet */
            dfs(dest);
            if (found_cycle)      /* propagate early exit */
                return;
        } else if (color[dest] == 1) {
            /* back‑edge → a cycle */
            found_cycle = true;
            return;
        }
        /* if color[dest] == 2 (black) we just continue */
    }

    color[src] = 2;                /* black – finished */
}

/* ------------------------------------------------------------------ */
static bool parse_int(const char *s, int *out)
{
    char *endptr;
    long  v = strtol(s, &endptr, 10);
    if (*endptr != '\0')            /* not a pure integer */
        return false;
    if (v < 0 || v >= MAXV)        /* out of allowed range */
        return false;
    *out = (int)v;
    return true;
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    /* ----------------------------------------------------------------
       Input validation – we need an even number of arguments after the
       program name (each edge is a pair).  The original program also
       limited the vertex range to 0‑7.
       ---------------------------------------------------------------- */
    if ((argc - 1) % 2 != 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* initialise adjacency matrix and colour array */
    memset(adj,   0, sizeof(adj));
    memset(color, 0, sizeof(color));
    found_cycle = false;

    /* ----------------------------------------------------------------
       Build the graph from the command line.
       argv[1] … argv[argc‑1] are interpreted as u1 v1 u2 v2 …
       ---------------------------------------------------------------- */
    for (int i = 1; i < argc; i += 2) {
        int u, v;
        if (!parse_int(argv[i],   &u) ||
            !parse_int(argv[i+1], &v)) {
            puts("INVALID_INPUT");
            return 1;
        }
        /* store edge u → v as adj[v][u] = 1 (the layout used by the
           original binary) */
        adj[v][u] = 1;
    }

    /* ----------------------------------------------------------------
       Run DFS from every vertex that has not been visited yet.
       ---------------------------------------------------------------- */
    for (int v = 0; v < MAXV; ++v) {
        if (color[v] == 0)
            dfs(v);
        if (found_cycle)
            break;
    }

    puts(found_cycle ? "CYCLE" : "ACYCLIC");
    return 0;
}
